import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/Events.css';
import { useLanguage } from '../context/LanguageContext';
import { useScrollToTop } from '../hooks/useScrollToTop';
import { API_BASE_URL } from '../utils/api';
import { getImageUrl } from '../utils/imageUtils';

const Events = () => {
    const { language } = useLanguage();
    const navigate = useNavigate();
    useScrollToTop(); // 確保頁面載入時滾動到頂部
    const [events, setEvents] = useState([]);
    const [loading, setLoading] = useState(true);
    const [visibleEvents, setVisibleEvents] = useState(3); // 初始顯示3個活動
    const [hasMore, setHasMore] = useState(true); // 是否還有更多活動可以加載
    const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

    // 监听窗口大小变化
    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768);
        };
        
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // 设置 HTML 元素的 lang 属性
    useEffect(() => {
        document.documentElement.lang = language;
    }, [language]);

    const text = {
        'zh-TW': {
            header: '活動資訊',
            subtitle: '探索我們的活動！這裡有過去的精彩回顧和即將到來的活動資訊。',
            loading: '載入中...',
            register: '立即報名',
            maxParticipants: '名額上限',
            showMore: '顯示更多',
            noMoreEvents: '沒有更多活動了',
            date: '日期:',
            location: '地點:',
            details: '專案細節',
            viewMoreSessions: '點選查看更多場次',
            status: {
                upcoming: '即將舉行',
                ongoing: '進行中',
                ended: '已結束'
            }
        },
        'en': {
            header: 'Events',
            subtitle: 'Explore our events! Here are past highlights and upcoming events.',
            loading: 'Loading...',
            register: 'Register Now',
            maxParticipants: 'Max Participants',
            showMore: 'Show More',
            noMoreEvents: 'No more events',
            date: 'Date:',
            location: 'Location:',
            details: 'Project Details',
            viewMoreSessions: 'Click to view more sessions',
            status: {
                upcoming: 'Upcoming',
                ongoing: 'Ongoing',
                ended: 'Ended'
            }
        }
    };

    useEffect(() => {
        const fetchEvents = async () => {
            try {
                const locale = language === 'zh-TW' ? 'zh-Hant-TW' : language;
                console.log(`Fetching events with sessions sorted by startDateTime`);
                
                // 添加去重參數
                const response = await fetch(
                    `${API_BASE_URL}/api/events?populate=*&sort[0]=session.startDateTime:desc&locale=${locale}&pagination[pageSize]=100`,
                    {
                        method: 'GET',
                        headers: {
                            'Accept': 'application/json',
                            'Content-Type': 'application/json'
                        }
                    }
                );

                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }

                const data = await response.json();
                console.log('Events data received:', data);
                
                if (data && data.data) {
                    // 獲取當前時間
                    const now = new Date();
                    
                    // 去除重複的活動（根據 ID）
                    const uniqueEvents = data.data.reduce((acc, current) => {
                        const exists = acc.find(item => item.id === current.id);
                        if (!exists) {
                            acc.push(current);
                        }
                        return acc;
                    }, []);

                    // 根據場次時間和狀態排序
                    const sortedEvents = uniqueEvents.sort((a, b) => {
                        const aStatus = a.attributes.status;
                        const bStatus = b.attributes.status;
                        
                        // 獲取最近的未結束場次
                        const aSession = a.attributes.session
                            ?.filter(s => new Date(s.startDateTime) >= now)
                            ?.sort((s1, s2) => new Date(s1.startDateTime) - new Date(s2.startDateTime))[0];
                            
                        const bSession = b.attributes.session
                            ?.filter(s => new Date(s.startDateTime) >= now)
                            ?.sort((s1, s2) => new Date(s1.startDateTime) - new Date(s2.startDateTime))[0];
                        
                        // 如果兩個活動狀態不同，upcoming 優先
                        if (aStatus !== bStatus) {
                            return aStatus === 'upcoming' ? -1 : 1;
                        }
                        
                        // 如果都是 upcoming，比較最近場次時間
                        if (aStatus === 'upcoming' && bStatus === 'upcoming') {
                            // 如果其中一個沒有未來場次，將其排在後面
                            if (!aSession) return 1;
                            if (!bSession) return -1;
                            
                            // 比較最近場次時間
                            return new Date(aSession.startDateTime) - new Date(bSession.startDateTime);
                        }
                        
                        // 如果都是已結束的活動，比較最後一個場次時間（較新的在前）
                        const aLastSession = a.attributes.session
                            ?.sort((s1, s2) => new Date(s2.startDateTime) - new Date(s1.startDateTime))[0];
                        const bLastSession = b.attributes.session
                            ?.sort((s1, s2) => new Date(s2.startDateTime) - new Date(s1.startDateTime))[0];
                            
                        // 如果沒有場次信息，排在最後
                        if (!aLastSession) return 1;
                        if (!bLastSession) return -1;
                        
                        // 比較最後場次時間（降序）
                        return new Date(bLastSession.startDateTime) - new Date(aLastSession.startDateTime);
                    });

                    console.log('Filtered and sorted events:', sortedEvents);
                    setEvents(sortedEvents);
                    setHasMore(sortedEvents.length > visibleEvents);
                } else {
                    console.error('Invalid response format:', data);
                }
            } catch (error) {
                console.error('Error fetching events:', error);
                if (error.response) {
                    console.error('Server error details:', {
                        status: error.response.status,
                        data: error.response.data
                    });
                }
            } finally {
                setLoading(false);
            }
        };

        fetchEvents();
    }, [language, visibleEvents]);

    const currentText = text[language];

    // 格式化日期時間
    const formatDateTime = (dateTime) => {
        return new Date(dateTime).toLocaleString(
            language === 'zh-TW' ? 'zh-TW' : 'en-US',
            { 
                year: 'numeric',
                month: 'long',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
                hour12: language !== 'zh-TW' // 英文使用 12 小時制，中文使用 24 小時制
            }
        );
    };

    // 格式化所有場次信息
    const getAllSessionsInfo = (sessions) => {
        if (!sessions || sessions.length === 0) return [];
        
        const now = new Date();
        
        // 過濾並排序場次
        const sortedSessions = sessions
            // 轉換日期並加入到物件中，以便排序
            .map(session => ({
                ...session,
                dateObj: new Date(session.startDateTime)
            }))
            // 按照與當前時間的接近程度排序
            .sort((a, b) => {
                const aDiff = Math.abs(a.dateObj - now);
                const bDiff = Math.abs(b.dateObj - now);
                return aDiff - bDiff;
            });

        // 只取前兩個場次
        const displaySessions = sortedSessions.slice(0, 2).map(session => {
            const date = session.dateObj;
            
            // 格式化日期
            const formattedDate = date.toLocaleDateString(
                language === 'zh-TW' ? 'zh-TW' : 'en-US',
                { 
                    month: 'short', 
                    day: 'numeric', 
                    weekday: 'short',
                    year: 'numeric'
                }
            );
            
            return {
                date: formattedDate,
                location: session.location
            };
        });

        // 如果有更多場次，添加標記
        const hasMoreSessions = sortedSessions.length > 2;
        
        return {
            sessions: displaySessions,
            hasMore: hasMoreSessions
        };
    };

    // 處理「顯示更多」按鈕點擊
    const handleShowMore = () => {
        // 每次增加3個活動
        const newVisibleEvents = visibleEvents + 3;
        setVisibleEvents(newVisibleEvents);
        
        // 檢查是否還有更多活動可以加載
        setHasMore(events.length > newVisibleEvents);
    };

    return (
        <div className="events-page">
            <div className="events-header">
                <h1>{currentText.header}</h1>
                <p>{currentText.subtitle}</p>
            </div>
            <div className="events-list">
                {loading ? (
                    <div className="loading">{currentText.loading}</div>
                ) : (
                    <div className="events-container">
                        <div className="events-grid">
                            {events?.slice(0, visibleEvents).map((event) => (
                                <div key={event.id} className="event-card" onClick={() => navigate(`/events/${event.id}`)}>
                                    {event.attributes.coverImage?.data && (
                                        <div className="event-image">
                                            <img 
                                                src={getImageUrl(event.attributes.coverImage)}
                                                alt={event.attributes.title}
                                                onError={(e) => {
                                                    e.target.onerror = null;
                                                    e.target.src = 'https://placehold.co/380x380?text=No+Image';
                                                }}
                                            />
                                        </div>
                                    )}
                                    <div className="event-content">
                                        <span className={`event-status ${event.attributes.status}`}>
                                            {currentText.status[event.attributes.status]}
                                        </span>
                                        <div className="title-container">
                                            <h2>{event.attributes.title}</h2>
                                        </div>
                                        <p className="event-description">
                                            {event.attributes.description}
                                        </p>
                                        {event.attributes.session && event.attributes.session.length > 0 && (
                                            <div className="event-brief-info">
                                                <div className="sessions-list">
                                                    {(() => {
                                                        const sessionInfo = getAllSessionsInfo(event.attributes.session);
                                                        return (
                                                            <>
                                                                {sessionInfo.sessions.map((session, index) => (
                                                        <div key={index} className="session-item">
                                                            <div className="brief-item brief-date">
                                                                <span><strong>{currentText.date}</strong> {session.date}</span>
                                                            </div>
                                                            <div className="brief-item brief-location">
                                                                <span><strong>{currentText.location}</strong> {session.location}</span>
                                                            </div>
                                                        </div>
                                                    ))}
                                                                {sessionInfo.hasMore && (
                                                                    <div className="more-sessions-link">
                                                                        {currentText.viewMoreSessions}
                                                                    </div>
                                                                )}
                                                            </>
                                                        );
                                                    })()}
                                                </div>
                                            </div>
                                        )}
                                        <div className="event-footer">
                                            <div className="button-group">
                                                <button 
                                                    className="register-button"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        navigate(`/events/${event.id}`);
                                                    }}
                                                    style={{ 
                                                        padding: isMobile ? '8px 15px' : '10px 18px',
                                                        fontSize: isMobile ? '0.85rem' : '0.95rem'
                                                    }}
                                                >
                                                    {currentText.register}
                                                </button>
                                                
                                                {event.attributes.eventlink && (
                                                    <a 
                                                        href={event.attributes.eventlink}
                                                        className="details-button"
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        onClick={(e) => e.stopPropagation()}
                                                    >
                                                        {currentText.details}
                                                    </a>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        
                        {/* 顯示更多按鈕 */}
                        {events.length > 0 && (
                            <div className="show-more-container">
                                {hasMore ? (
                                    <button className="show-more-button" onClick={handleShowMore}>
                                        {currentText.showMore}
                                    </button>
                                ) : (
                                    <p className="no-more-events">{currentText.noMoreEvents}</p>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default Events; 